#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    string abbreviateProduct(int left, int right) {
        const long long BASE = 1000000000;
        vector<int> product(1, 1);

        for (int value = left; value <= right; ++value) {
            long long carry = 0;
            for (int& block : product) {
                long long current = 1LL * block * value + carry;
                block = static_cast<int>(current % BASE);
                carry = current / BASE;
            }
            if (carry > 0) {
                product.push_back(static_cast<int>(carry));
            }
        }

        string digits = to_string(product.back());
        digits.reserve(product.size() * 9);

        for (int i = static_cast<int>(product.size()) - 2; i >= 0; --i) {
            string block = to_string(product[i]);
            digits.append(9 - block.size(), '0');
            digits += block;
        }

        int trailingZeros = 0;
        while (digits.back() == '0') {
            digits.pop_back();
            ++trailingZeros;
        }

        if (digits.size() > 10) {
            digits = digits.substr(0, 5) + "..." +
                     digits.substr(digits.size() - 5);
        }

        return digits + "e" + to_string(trailingZeros);
    }
};
