class Solution {
public:
    bool arrayStringsAreEqual(vector<string>& word1, vector<string>& word2) {
        size_t i = 0, j = 0, p = 0, q = 0;

        while (i < word1.size() && j < word2.size()) {
            if (word1[i][p] != word2[j][q]) {
                return false;
