    vector<int> numSmallerByFrequency(vector<string>& queries, vector<string>& words) {
        auto frequency = [](const string& s) {
            char smallest = '{';
            int count = 0;
            for (char c : s) {
                if (c < smallest) {
                    smallest = c;
                    count = 1;
                } else if (c == smallest) {
                    ++count;
                }
            }
            return count;
        };

        int suffix[12] = {};
        for (const string& word : words) {
            ++suffix[frequency(word)];
        }

        for (int i = 10; i >= 1; --i) {
            suffix[i] += suffix[i + 1];
        }

        vector<int> answer;
        answer.reserve(queries.size());
        for (const string& query : queries) {
            answer.push_back(suffix[frequency(query) + 1]);
        }
        return answer;
    }
};
