using namespace std;

class Solution {
public:
    int countMaxOrSubsets(vector<int>& nums) {
        int target = 0;
        for (int num : nums) {
            target |= num;
        }

        int n = static_cast<int>(nums.size());

        auto dfs = [&](auto&& self, int index, int currentOr) -> int {
            if (currentOr == target) {
                return 1 << (n - index);
            }
            if (index == n) {
                return 0;
            }

            return self(self, index + 1, currentOr) +
                   self(self, index + 1, currentOr | nums[index]);
        };

        return dfs(dfs, 0, 0);
    }
};
