#include <vector>
#include <queue>

class MKAverage {
private:
    static constexpr int LIMIT = 100000;

    int m_, k_;
    std::queue<int> window;
    std::vector<int> counts;
    std::vector<long long> sums;

    void update(int value, int delta) {
        for (int i = value; i <= LIMIT; i += i & -i) {
            counts[i] += delta;
            sums[i] += 1LL * value * delta;
        }
    }

    // Returns the sum of the smallest 'count' elements.
    long long sumSmallest(int count) const {
        if (count == 0) return 0;

        int index = 0;
        long long result = 0;

        for (int step = 1 << 16; step > 0; step >>= 1) {
            int next = index + step;
            if (next <= LIMIT && counts[next] < count) {
                index = next;
                count -= counts[next];
                result += sums[next];
            }
        }

        return result + 1LL * count * (index + 1);
    }

public:
    MKAverage(int m, int k)
        : m_(m), k_(k), counts(LIMIT + 1, 0), sums(LIMIT + 1, 0) {
    }

    void addElement(int num) {
        window.push(num);
        update(num, 1);

        if (static_cast<int>(window.size()) > m_) {
            update(window.front(), -1);
            window.pop();
        }
    }

    int calculateMKAverage() {
        if (static_cast<int>(window.size()) < m_) return -1;

        long long middleSum = sumSmallest(m_ - k_) - sumSmallest(k_);
        return static_cast<int>(middleSum / (m_ - 2 * k_));
    }
};
