        vector<vector<int>> gcdValue(m, vector<int>(m));
        for (int i = 0; i < m; ++i) {
            for (int j = i + 1; j < m; ++j) {
                gcdValue[i][j] = gcd(nums[i], nums[j]);
            }
        }

        int totalMasks = 1 << m;
        vector<int> dp(totalMasks, 0);

        for (int mask = 1; mask < totalMasks; ++mask) {
            int count = __builtin_popcount(static_cast<unsigned>(mask));
            if (count % 2 != 0) continue;

            int operation = count / 2;
            for (int i = 0; i < m; ++i) {
                if (!(mask & (1 << i))) continue;
                for (int j = i + 1; j < m; ++j) {
                    if (!(mask & (1 << j))) continue;

                    int previous = mask ^ (1 << i) ^ (1 << j);
                    dp[mask] = max(dp[mask],
                                   dp[previous] + operation * gcdValue[i][j]);
                }
            }
        }

        return dp[totalMasks - 1];
    }
};
