    long long maxRunTime(int n, vector<int>& batteries) {
        long long total = 0;
        for (int capacity : batteries) {
            total += capacity;
        }

        long long low = 0, high = total / n;

        while (low < high) {
            long long mid = low + (high - low + 1) / 2;
            long long available = 0;

            for (int capacity : batteries) {
                available += min<long long>(capacity, mid);
            }

            if (available >= mid * n) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }

        return low;
    }
