        for (int node : initial) {
            infected[node] = true;
        }

        // Find connected components containing only initially clean nodes.
        vector<int> component(n, -1);
        vector<int> sizes;

        for (int start = 0; start < n; ++start) {
            if (infected[start] || component[start] != -1) {
                continue;
            }

            int id = sizes.size();
            vector<int> nodes = {start};
            component[start] = id;

            for (int i = 0; i < static_cast<int>(nodes.size()); ++i) {
                int u = nodes[i];
                for (int v = 0; v < n; ++v) {
                    if (graph[u][v] && !infected[v] && component[v] == -1) {
                        component[v] = id;
                        nodes.push_back(v);
                    }
                }
            }

            sizes.push_back(nodes.size());
        }

        // A component is saved only if exactly one infected node touches it.
        int count = sizes.size();
        vector<int> owner(count, -1);

        for (int node : initial) {
            vector<bool> touched(count, false);
            for (int v = 0; v < n; ++v) {
                if (graph[node][v] && component[v] != -1) {
                    touched[component[v]] = true;
                }
