using namespace std;

class Solution {
public:
    int minAreaRect(vector<vector<int>>& points) {
        constexpr long long BASE = 40001;
        unordered_set<long long> present;
        present.reserve(points.size() * 2);

        for (const auto& p : points) {
            present.insert(p[0] * BASE + p[1]);
        }

        int answer = INT_MAX;
        int n = points.size();

        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int x1 = points[i][0], y1 = points[i][1];
                int x2 = points[j][0], y2 = points[j][1];

                if (x1 == x2 || y1 == y2) continue;

                int area = abs(x1 - x2) * abs(y1 - y2);
                if (area >= answer) continue;

                if (present.count(x1 * BASE + y2) &&
                    present.count(x2 * BASE + y1)) {
                    answer = area;
                }
            }
        }

        return answer == INT_MAX ? 0 : answer;
    }
};
