#include <vector>
using namespace std;

class Solution {
public:
    int numOfWays(vector<int>& nums) {
        constexpr long long MOD = 1000000007;
        int n = nums.size();

        vector<long long> fact(n + 1, 1), invFact(n + 1, 1);
        for (int i = 1; i <= n; ++i) {
            fact[i] = fact[i - 1] * i % MOD;
        }

        long long base = fact[n], inverse = 1;
        for (long long exponent = MOD - 2; exponent; exponent >>= 1) {
            if (exponent & 1) inverse = inverse * base % MOD;
            base = base * base % MOD;
        }

        invFact[n] = inverse;
        for (int i = n; i >= 1; --i) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        // Node indices are their positions in the insertion order.
        vector<int> left(n, -1), right(n, -1);
        for (int i = 1; i < n; ++i) {
            int node = 0;
            while (true) {
                int& child = nums[i] < nums[node] ? left[node] : right[node];
                if (child == -1) {
                    child = i;
                    break;
                }
                node = child;
            }
        }

        vector<int> size(n, 1);
        vector<long long> ways(n, 1);

        // Every child was inserted after its parent, so reverse order is bottom-up.
        for (int node = n - 1; node >= 0; --node) {
            int l = left[node], r = right[node];
            int leftSize = l == -1 ? 0 : size[l];
            int rightSize = r == -1 ? 0 : size[r];

            size[node] = leftSize + rightSize + 1;

            // Interleave valid left and right orders while preserving each order.
            ways[node] = fact[leftSize + rightSize]
                         * invFact[leftSize] % MOD
                         * invFact[rightSize] % MOD;

            if (l != -1) ways[node] = ways[node] * ways[l] % MOD;
            if (r != -1) ways[node] = ways[node] * ways[r] % MOD;
        }

        // Exclude the original ordering.
        return static_cast<int>((ways[0] - 1 + MOD) % MOD);
    }
};
