class Solution {
public:
    int numTriplets(vector<int>& nums1, vector<int>& nums2) {
        auto countTriplets = [](const vector<int>& singles,
                                const vector<int>& pairs) -> long long {
            unordered_map<long long, int> squareFrequency;
            squareFrequency.reserve(singles.size());

            for (int value : singles) {
                ++squareFrequency[1LL * value * value];
            }

            long long count = 0;
            for (int j = 0; j < static_cast<int>(pairs.size()); ++j) {
                for (int k = j + 1; k < static_cast<int>(pairs.size()); ++k) {
                    long long product = 1LL * pairs[j] * pairs[k];
                    auto it = squareFrequency.find(product);
                    if (it != squareFrequency.end()) {
                        count += it->second;
                    }
                }
            }
            return count;
        };

        return static_cast<int>(countTriplets(nums1, nums2) +
                                countTriplets(nums2, nums1));
    }
};
