        int m = slices.size();
        int n = m / 3;
        const int NEG = -1000000000;

        auto solve = [&](int left, int right) {
            vector<int> prev2(n + 1, NEG);
            vector<int> prev1(n + 1, NEG);
            vector<int> curr(n + 1, NEG);
            prev2[0] = prev1[0] = 0;

            for (int i = left; i <= right; ++i) {
                curr[0] = 0;
                for (int count = 1; count <= n; ++count) {
