                        curr[count] = max(
                            curr[count],
                            prev2[count - 1] + slices[i]
                        );
                    }
                }
                prev2.swap(prev1);
                prev1.swap(curr);
            }

            return prev1[n];
        };

        return max(solve(0, m - 2), solve(1, m - 1));
    }
};
