        int n = static_cast<int>(adjacentPairs.size()) + 1;
        unordered_map<int, vector<int>> graph;
        graph.reserve(n);

        for (const auto& pair : adjacentPairs) {
            graph[pair[0]].push_back(pair[1]);
            graph[pair[1]].push_back(pair[0]);
        }

        vector<int> result;
        result.reserve(n);

        for (const auto& entry : graph) {
            if (entry.second.size() == 1) {
                result.push_back(entry.first);
                result.push_back(entry.second[0]);
                break;
            }
        }

        while (result.size() < static_cast<size_t>(n)) {
            int previous = result[result.size() - 2];
            const auto& neighbors = graph.at(result.back());
            result.push_back(neighbors[0] == previous
