class Solution {
public:
    vector<double> medianSlidingWindow(vector<int>& nums, int k) {
        multiset<int> lower, upper;
        vector<double> result;
        result.reserve(nums.size() - k + 1);

        for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
            if (lower.empty() || nums[i] <= *lower.rbegin()) {
                lower.insert(nums[i]);
            } else {
                upper.insert(nums[i]);
            }

            if (i >= k) {
                auto it = lower.find(nums[i - k]);
                if (it != lower.end()) {
                    lower.erase(it);
                } else {
                    upper.erase(upper.find(nums[i - k]));
                }
            }

            while (lower.size() > upper.size() + 1) {
                auto it = prev(lower.end());
                upper.insert(*it);
                lower.erase(it);
            }
            while (lower.size() < upper.size()) {
                auto it = upper.begin();
                lower.insert(*it);
                upper.erase(it);
            }

            if (i >= k - 1) {
                if (k % 2 == 1) {
                    result.push_back(*lower.rbegin());
                } else {
                    result.push_back(
                        (static_cast<double>(*lower.rbegin()) +
                         static_cast<double>(*upper.begin())) / 2.0
                    );
                }
            }
        }

        return result;
    }
