public:
    vector<int> getCoprimes(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();
        vector<vector<int>> graph(n);
        for (const auto& edge : edges) {
            graph[edge[0]].push_back(edge[1]);
            graph[edge[1]].push_back(edge[0]);
        }

        vector<int> coprime[51];
        for (int x = 1; x <= 50; ++x) {
            for (int y = 1; y <= 50; ++y) {
                if (gcd(x, y) == 1) {
                    coprime[x].push_back(y);
                }
            }
        }

        vector<int> ans(n, -1);
        // For each value, store (depth, node) along the current root path.
        vector<pair<int, int>> ancestors[51];

        struct Event {
            int node, parent, depth;
            bool exiting;
        };

        vector<Event> events;
        events.reserve(2 * n);
        events.push_back({0, -1, 0, false});

        while (!events.empty()) {
            Event event = events.back();
            events.pop_back();

            int u = event.node;
            int value = nums[u];

            if (event.exiting) {
                ancestors[value].pop_back();
                continue;
            }

            int bestDepth = -1;
            for (int other : coprime[value]) {
                if (!ancestors[other].empty()) {
                    const auto& candidate = ancestors[other].back();
                    if (candidate.first > bestDepth) {
                        bestDepth = candidate.first;
                        ans[u] = candidate.second;
                    }
                }
            }

            ancestors[value].push_back({event.depth, u});
            events.push_back({u, event.parent, event.depth, true});

            for (int v : graph[u]) {
                if (v != event.parent) {
                    events.push_back({v, u, event.depth + 1, false});
                }
            }
        }

        return ans;
    }
};
