            for (int j = 1; j <= m; ++j) {
                bool previous = dp[j];

                if (p[j - 1] == '*') {
                    dp[j] = dp[j] || dp[j - 1];
                } else {
                    dp[j] = diagonal &&
                            (p[j - 1] == '?' || p[j - 1] == c);
                }

                diagonal = previous;
            }
        }

        return dp[m];
    }
